using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesItemCount()
    {
        _cart.AddItem("SKU1", 10.00m, 2);

        Assert.AreEqual(1, _cart.ItemCount);
    }

    [TestMethod]
    public void AddItem_MultipleItems_AccumulatesCount()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU2", 5.00m, 3);

        Assert.AreEqual(2, _cart.ItemCount);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 10m, 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddItem_InvalidPrice_Throws(int price)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU1", price, 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQty_Throws(int qty)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU1", 10m, qty));
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU1", 10m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_DecreasesCount()
    {
        _cart.AddItem("SKU1", 10m, 1);
        _cart.AddItem("SKU2", 5m, 2);

        _cart.RemoveItem("SKU1");

        Assert.AreEqual(1, _cart.ItemCount);
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        _cart.AddItem("SKU1", 10m, 1);

        Assert.IsFalse(_cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_EmptyCart_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("SKU1"));
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_SingleItem_ReturnsPriceTimesQty()
    {
        _cart.AddItem("SKU1", 25.50m, 2);

        Assert.AreEqual(51.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("SKU1", 10m, 2); // 20
        _cart.AddItem("SKU2", 5m, 3);  // 15

        Assert.AreEqual(35m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _cart.AddItem("SKU1", 10m, 1);
        _cart.AddItem("SKU2", 20m, 1);
        _cart.RemoveItem("SKU1");

        Assert.AreEqual(20m, _cart.GetTotal());
    }

    // --- ApplyPromoCode ---

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyPromoCode_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("SKU1", 100m, 1);

        _cart.ApplyPromoCode(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_DoesNotChangeTotal()
    {
        _cart.AddItem("SKU1", 50m, 2);
        _cart.ApplyPromoCode("BOGUS");

        Assert.AreEqual(100m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive_AppliesDiscount()
    {
        _cart.AddItem("SKU1", 100m, 1);

        _cart.ApplyPromoCode("save10");

        Assert.AreEqual(90m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void ApplyPromoCode_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyPromoCode(code!));
    }

    [TestMethod]
    public void ApplyPromoCode_AppliedTwice_UsesLatestCode()
    {
        _cart.AddItem("SKU1", 100m, 1);

        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");

        Assert.AreEqual(80m, _cart.GetTotal());
    }
}

